#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

typedef struct {
    int g;
    int cnt;
} GCDBlock;

typedef struct {
    long long ans;
    int pref_sz;
    int suff_sz;
    GCDBlock pref[32];
    GCDBlock suff[32];
} Node;

int S[MAXN];
Node tree[4 * MAXN];

static inline int gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

void merge(Node* res, const Node* L, const Node* R) {
    res->ans = L->ans + R->ans;

    // Cross pairs
    for (int i = 0; i < L->suff_sz; ++i) {
        if (L->suff[i].g == 1) continue;
        for (int j = 0; j < R->pref_sz; ++j) {
            if (R->pref[j].g == 1) continue;
            if (gcd(L->suff[i].g, R->pref[j].g) > 1) {
                res->ans += (long long)L->suff[i].cnt * R->pref[j].cnt;
            }
        }
    }

    // Prefixes
    res->pref_sz = L->pref_sz;
    for (int i = 0; i < L->pref_sz; ++i) {
        res->pref[i] = L->pref[i];
    }
    int cur_g = L->pref[L->pref_sz - 1].g;
    for (int j = 0; j < R->pref_sz; ++j) {
        int ng = gcd(cur_g, R->pref[j].g);
        if (ng == res->pref[res->pref_sz - 1].g) {
            res->pref[res->pref_sz - 1].cnt += R->pref[j].cnt;
        } else {
            res->pref[res->pref_sz].g = ng;
            res->pref[res->pref_sz].cnt = R->pref[j].cnt;
            res->pref_sz++;
        }
    }

    // Suffixes
    res->suff_sz = R->suff_sz;
    for (int i = 0; i < R->suff_sz; ++i) {
        res->suff[i] = R->suff[i];
    }
    cur_g = R->suff[R->suff_sz - 1].g;
    for (int i = 0; i < L->suff_sz; ++i) {
        int ng = gcd(cur_g, L->suff[i].g);
        if (ng == res->suff[res->suff_sz - 1].g) {
            res->suff[res->suff_sz - 1].cnt += L->suff[i].cnt;
        } else {
            res->suff[res->suff_sz].g = ng;
            res->suff[res->suff_sz].cnt = L->suff[i].cnt;
            res->suff_sz++;
        }
    }
}

void make_leaf(Node* node, int val) {
    node->ans = (val > 1) ? 1 : 0;
    node->pref_sz = 1;
    node->pref[0].g = val;
    node->pref[0].cnt = 1;

    node->suff_sz = 1;
    node->suff[0].g = val;
    node->suff[0].cnt = 1;
}

void build(int u, int l, int r) {
    if (l == r) {
        make_leaf(&tree[u], S[l]);
        return;
    }
    int mid = (l + r) >> 1;
    build(u << 1, l, mid);
    build((u << 1) | 1, mid + 1, r);
    merge(&tree[u], &tree[u << 1], &tree[(u << 1) | 1]);
}

void update(int u, int l, int r, int idx, int val) {
    if (l == r) {
        make_leaf(&tree[u], val);
        return;
    }
    int mid = (l + r) >> 1;
    if (idx <= mid) {
        update(u << 1, l, mid, idx, val);
    } else {
        update((u << 1) | 1, mid + 1, r, idx, val);
    }
    merge(&tree[u], &tree[u << 1], &tree[(u << 1) | 1]);
}

void query(int u, int l, int r, int ql, int qr, Node* res, int* has_res) {
    if (ql <= l && r <= qr) {
        if (!(*has_res)) {
            *res = tree[u];
            *has_res = 1;
        } else {
            Node temp;
            merge(&temp, res, &tree[u]);
            *res = temp;
        }
        return;
    }
    int mid = (l + r) >> 1;
    if (ql <= mid) {
        query(u << 1, l, mid, ql, qr, res, has_res);
    }
    if (qr > mid) {
        query((u << 1) | 1, mid + 1, r, ql, qr, res, has_res);
    }
}

// Fast I/O
static inline int readInt() {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();
    if (c == EOF) return 0;
    int res = 0;
    while (c >= '0' && c <= '9') {
        res = res * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return res;
}

static inline void printLongLong(long long n) {
    if (n == 0) {
        putchar_unlocked('0');
        putchar_unlocked('\n');
        return;
    }
    char buf[25];
    int idx = 0;
    while (n > 0) {
        buf[idx++] = (char)('0' + (n % 10));
        n /= 10;
    }
    while (idx > 0) {
        putchar_unlocked(buf[--idx]);
    }
    putchar_unlocked('\n');
}

int main() {
    int n = readInt();
    int m = readInt();
    for (int i = 1; i <= n; ++i) {
        S[i] = readInt();
    }

    build(1, 1, n);

    for (int k = 0; k < m; ++k) {
        int t = readInt();
        if (t == 1) {
            int i = readInt();
            int v = readInt();
            update(1, 1, n, i, v);
        } else {
            int e = readInt();
            int d = readInt();
            Node res;
            int has_res = 0;
            query(1, 1, n, e, d, &res, &has_res);
            printLongLong(res.ans);
        }
    }

    return 0;
}
